pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 initializerVersion) public {
        // Initialize the contract
        address mockConfig = address(new MockLRTConfig());
        c.initialize(mockConfig);

        // Check initial paused state should be false
        bool initiallyPaused = c.paused();
        assertTrue(!initiallyPaused, "Initial paused state must be false");

        // Pause the contract
        vm.startPrank(mockConfig);
        c.pause();
        vm.stopPrank();

        // After pause, paused() must return true
        bool afterPause = c.paused();
        assertTrue(afterPause, "Paused state must be true after pause");
    }
}

