contract LRTConfigHelper {
    mapping(bytes32 => mapping(address => bool)) private _roles;
    mapping(address => bool) private _supportedAssets;
    mapping(address => uint256) private _depositLimits;
    address[] private _supportedAssetList;

    bytes32 public constant DEFAULT_ADMIN_ROLE = 0x00;
    bytes32 public constant MANAGER = keccak256("MANAGER");

    constructor() {
        _roles[DEFAULT_ADMIN_ROLE][msg.sender] = true;
    }

    function grantManager(address account) external {
        _roles[MANAGER][account] = true;
    }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        return _roles[role][account];
    }

    function isSupportedAsset(address asset) external view returns (bool) {
        return _supportedAssets[asset];
    }

    function rsETH() external pure returns (address) {
        return address(0);
    }

    function getContract(bytes32) external pure returns (address) {
        return address(0);
    }

    function depositLimitByAsset(address asset) external view returns (uint256) {
        return _depositLimits[asset];
    }

    function getSupportedAssetList() external view returns (address[] memory) {
        return _supportedAssetList;
    }

    function assetStrategy(address) external pure returns (address) {
        return address(0);
    }

    function setSupportedAsset(address asset, uint256 limit) external {
        if (!_supportedAssets[asset]) {
            _supportedAssets[asset] = true;
            _supportedAssetList.push(asset);
        }
        _depositLimits[asset] = limit;
    }
}

