pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Initialize with ourselves as the lrtConfig so the contract has a valid config
        c.initialize(address(this));
    }
    function testFuzz_property(address newConfig, address caller) public {
        // Admissible domain: addresses that are not the default admin (which is the initializer msg.sender, i.e. this test contract)
        vm.assume(caller != address(this));
        vm.assume(newConfig != address(0));
        vm.assume(newConfig != address(c));

        address beforeConfig = address(c.lrtConfig());

        bool ok;
        vm.prank(caller);
        try c.updateLRTConfig(newConfig) {
            ok = true;
        } catch {
            ok = false;
        }

        address afterConfig = address(c.lrtConfig());

        // Rule: if the call does not revert, the config must have changed from before.
        // The reference never allows a non-admin to change config (always reverts),
        // so before == after for all admissible callers. The bug allows a non-admin to
        // change it, so at least one caller succeeds and after != before.
        assertTrue(!ok || afterConfig != beforeConfig);
    }
}

