pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address configAddr) public {
        // Keep the input address admissible: non-zero
        vm.assume(configAddr != address(0));

        // The initializer modifier in C checks `_initialized < 1` in the reference
        // and `_initialized < 0` (always false) in the mutant.
        // The reference succeeds; the mutant always reverts.
        // We must observe the public variable `maxNodeDelegatorCount` after the call.
        bool ok;
        try c.initialize(configAddr) { ok = true; } catch { ok = false; }

        // If `initialize` succeeded, `maxNodeDelegatorCount` must equal the value set inside `initialize` (10).
        // If it failed, the state variable was never initialized by the contract, so it remains its default (0).
        // The reference will always have `ok == true` and `maxNodeDelegatorCount == 10`.
        // The mutant will always have `ok == false`, so `maxNodeDelegatorCount != 10`.
        assertTrue(
            ok ? c.maxNodeDelegatorCount() == 10 : c.maxNodeDelegatorCount() != 10
        );
    }
}

